mapper.select:
SELECT COALESCE(SUM(t.total_amount), 0)
FROM orders t
WHERE t.status = 'PAID'
  AND (t.order_type IS NULL OR t.order_type = 'NORMAL')
  AND t.pay_time IS NOT NULL
  AND t.pay_time >= #{start}
  AND t.pay_time <= #{end}
  AND t.create_by = #{username}

      AND t.tenant_id = #{tenantId}

SELECT d.id AS deptId, d.name AS deptName, COUNT(t.id) AS orderCount, COALESCE(SUM(t.total_amount), 0) AS orderAmount FROM sys_department d LEFT JOIN ( SELECT user_id, MIN(department_id) AS primary_dept_id FROM sys_user_department WHERE deleted = 0 GROUP BY user_id ) ud ON ud.primary_dept_id = d.id LEFT JOIN sys_user u ON u.id = ud.user_id AND u.deleted = 0 LEFT JOIN orders t ON t.create_by = u.username AND t.status = 'PAID' AND (t.order_type IS NULL OR t.order_type = 'NORMAL') AND t.pay_time IS NOT NULL AND t.pay_time >= #{start} AND t.pay_time <= #{end}
AND t.tenant_id = #{ctx.tenantId}
WHERE d.deleted = 0
AND d.tenant_id = #{ctx.tenantId}
GROUP BY d.id, d.name HAVING orderCount > 0 OR orderAmount > 0 ORDER BY orderAmount DESC
